-- Separate menu books and independent Hungarian / English documents.
create table public.menu_books (
  id uuid primary key default gen_random_uuid(),
  title text not null check (char_length(trim(title)) between 1 and 80),
  description text not null default '' check (char_length(description) <= 300),
  sort_order integer not null default 0,
  created_at timestamptz not null default now()
);
create table public.menu_versions (
  id uuid primary key default gen_random_uuid(),
  menu_id uuid not null references public.menu_books(id) on delete cascade,
  language text not null check (language in ('hu', 'en')),
  pdf_path text check (pdf_path ~ '^[A-Za-z0-9._-]+\.pdf$'),
  pages jsonb not null check (jsonb_typeof(pages) = 'array' and jsonb_array_length(pages) between 1 and 40),
  updated_at timestamptz not null default now(),
  unique (menu_id, language)
);
alter table public.menu_books enable row level security;
alter table public.menu_versions enable row level security;
grant select on public.menu_books, public.menu_versions to anon, authenticated;
grant insert, update, delete on public.menu_books, public.menu_versions to authenticated;
create policy "Public reads menu books" on public.menu_books for select to anon, authenticated using (true);
create policy "Public reads menu versions" on public.menu_versions for select to anon, authenticated using (true);
create policy "Admins manage menu books" on public.menu_books for all to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));
create policy "Admins manage menu versions" on public.menu_versions for all to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));

